import {paintPixelWordmark,paintPixelIcon} from './pixel-art.mjs?v=ember-16';
import {PlayerRecords,escapeHTML} from './records.mjs?v=ember-12';
import {sceneAt,scenes} from './worlds.mjs?v=ember-16';
import {GameAudio} from './audio.mjs?v=ember-13';
import {createGame,step,chooseUpgrade,talents,classes,categories,monsters,MAP,activeSkills,activate,threatBudget,liveThreat,MAX_ENEMIES,essences,totalShield} from './engine.mjs?v=ember-16';
import {Renderer} from './render.mjs?v=ember-16';
const $=selector=>document.querySelector(selector),canvas=$('#game'),overlay=$('#overlay'),renderer=new Renderer(canvas);
let selectedClass='archer',menuPage='home',g=createGame(),keys=new Set(),touch={x:0,y:0},pointer=null,last=0,accumulator=0,hudClock=0,screenStatus='',best=0,sound=true,lastKills=0,lastHealth=100,fullscreenTransition=0,lastDraw=0,drawStatus='';
try{best=Number(localStorage.getItem('emberfall-best'))||0}catch{}
const format=time=>`${String(Math.floor(time/60)).padStart(2,'0')}:${String(Math.max(0,Math.floor(time%60))).padStart(2,'0')}`;
const announce=text=>$('#live-region').textContent=text;
const records=new PlayerRecords({changed:updateProfile});
function updateProfile(){
 $('#records-status').textContent=records.message;
 const runStatus=$('#run-sync-status');if(runStatus)runStatus.textContent=records.message;
 $('#player-identity').textContent=records.player?'Player ID: '+records.player.id:'Your account gets a random player ID. It is remembered on this browser.';
 const p=records.player;
 $('#personal-record').textContent=p?.survivedMs?`Your online best: ${format(p.survivedMs/1000)} · ${p.kills} kills · ${classes.find(c=>c.id===p.classId)?.name||p.classId}`:'Complete a run to set your first online record.';
}
let leaderboardLoading=false;
async function loadLeaderboard(){
 if(leaderboardLoading)return;leaderboardLoading=true;
 $('#refresh-leaderboard').disabled=true;$('#leaderboard-content').textContent='Loading survivors…';
 try{
  await records.flush();const entries=await records.leaderboard();
  $('#leaderboard-content').innerHTML=entries.length?`<div class="leaderboard-scroll"><table class="leaderboard-table"><caption class="sr-only">Longest survival records</caption><thead><tr><th scope="col">Rank</th><th scope="col">Survivor</th><th scope="col">Time</th><th scope="col">Kills</th><th scope="col">Class</th></tr></thead><tbody>${entries.map(p=>`<tr ${p.id===records.player?.id?'class="your-score"':''}><td>${p.rank}</td><th scope="row"><span>${escapeHTML(p.nickname)}${p.id===records.player?.id?' (you)':''}</span><small>${escapeHTML(p.id.slice(0,8))}</small></th><td>${format(p.survivedMs/1000)}</td><td>${p.kills}</td><td>${escapeHTML(classes.find(c=>c.id===p.classId)?.name||p.classId)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="guide-help">No records yet. Carry the first flame.</p>';
 }catch(error){$('#leaderboard-content').textContent=error.message}
 finally{leaderboardLoading=false;$('#refresh-leaderboard').disabled=false}
}
$('#leaderboard-button').onclick=()=>{openModal('#leaderboard-dialog');$('#player-nickname').value=records.identity?.nickname||'';updateProfile();void loadLeaderboard()};
$('#leaderboard-dialog .close').onclick=()=>$('#leaderboard-dialog').close();
$('#refresh-leaderboard').onclick=()=>loadLeaderboard();
$('#player-form').onsubmit=async event=>{event.preventDefault();$('#save-player').disabled=true;try{await records.saveNickname($('#player-nickname').value);await loadLeaderboard()}catch(error){records.notify(error.message)}finally{$('#save-player').disabled=false}};
updateProfile();void records.restore();
window.addEventListener('online',()=>{void records.flush()});
const colorFor=t=>categories[t.category].color;
const soundtrack=new GameAudio();
function tone(frequency=330,length=.07,type='sine',volume=.02){soundtrack.unlock();soundtrack.note(frequency,length,type,volume)}
function syncAudio(){sound=!soundtrack.settings.muted;$('#sound').textContent=sound?'ON':'OFF';$('#sound').setAttribute('aria-label',sound?'Mute audio (M)':'Unmute audio (M)');$('#sound').setAttribute('aria-pressed',String(!sound));$('#music-volume').value=String(Math.round(soundtrack.settings.music*100));$('#effects-volume').value=String(Math.round(soundtrack.settings.effects*100));$('#music-value').textContent=$('#music-volume').value+'%';$('#effects-value').textContent=$('#effects-volume').value+'%';$('#audio-mute').checked=!sound;$('#reduce-motion').checked=renderer.reducedMotion}
function toggleAudio(){soundtrack.unlock();soundtrack.set('muted',!soundtrack.settings.muted);syncAudio();soundtrack.cue('ui')}
$('#sound').onclick=toggleAudio;
$('#settings').onclick=()=>{soundtrack.unlock();syncAudio();openModal('#audio-dialog')};
$('#audio-dialog .close').onclick=()=>$('#audio-dialog').close();
for(const [id,key]of [['music-volume','music'],['effects-volume','effects']])$('#'+id).oninput=e=>{soundtrack.unlock();soundtrack.set(key,Number(e.target.value)/100);syncAudio()};
$('#effects-volume').onchange=()=>soundtrack.cue('slash');
$('#audio-mute').onchange=e=>{soundtrack.unlock();soundtrack.set('muted',e.target.checked);syncAudio()};
$('#reduce-motion').onchange=e=>{renderer.reducedMotion=e.target.checked;try{localStorage.setItem('emberfall-motion',renderer.reducedMotion?'reduced':'full')}catch{}drawStatus='';renderer.draw(g);for(const portrait of overlay.querySelectorAll?.('[data-portrait],[data-home-portrait]')||[])renderer.portrait(portrait,portrait.dataset.portrait||portrait.dataset.homePortrait,0)};
syncAudio();decorateIcons();
async function fullscreen(){fullscreenTransition=performance.now()+1200;try{if(document.fullscreenElement)await document.exitFullscreen?.();else await document.documentElement?.requestFullscreen?.()}catch{announce('Fullscreen is unavailable in this browser. The game still fills your window.')}renderer.resize()}
$('#fullscreen').onclick=fullscreen;
document.addEventListener('fullscreenchange',()=>{$('#fullscreen').setAttribute('aria-label',document.fullscreenElement?'Exit fullscreen':'Enter fullscreen');renderer.resize()});
new ResizeObserver(()=>{renderer.resize();renderer.draw(g)}).observe(canvas);
function decorateIcons(root=document){for(const icon of root.querySelectorAll?.('[data-pixel-icon]')||[])paintPixelIcon(icon,icon.dataset.pixelIcon,icon.dataset.color||'#e1cd93')}
function setPanel(html){overlay.innerHTML=html;overlay.classList.remove('hidden');decorateIcons(overlay)}
function prepareMenu(page){menuPage=page;drawStatus='';g=createGame(Date.now(),selectedClass);screenStatus='ready';clearInput();$('#run-hud').hidden=true;$('#game-root').classList.remove('running');$('#game-root').classList.toggle('home-screen',page==='home');$('#pause').disabled=true;overlay.scrollTop=0;overlay.classList.toggle('home-overlay',page==='home')}
function showHome(){prepareMenu('home');
 setPanel(`<main class="home-menu" aria-labelledby="home-title"><div class="home-content"><div class="eyebrow">ONE HERO. AN ENDLESS HORDE.</div><h1 id="home-title"><span class="sr-only">Emberfall</span><canvas id="pixel-wordmark" width="500" height="112" aria-hidden="true"></canvas><span>The Hollow Wood</span></h1><p class="home-intro">The wood is closing in.<br>Carry the flame a little farther.</p><div class="home-actions"><button id="play" class="gold-button">Play<span aria-hidden="true">→</span></button><div class="home-links"><button id="home-guide" class="secondary-button">Field guide</button><button id="home-leaderboard" class="secondary-button">Leaderboard</button><button id="home-settings" class="secondary-button">Settings</button></div></div><p class="home-controls">Move with WASD or arrows · Space to unleash your ability</p></div><div class="home-art" aria-hidden="true"><div class="home-halo"></div><canvas class="home-star" data-pixel-icon="arcane" width="24" height="24"></canvas><div class="home-party">${['mage','fighter','archer'].map(id=>`<canvas data-home-portrait="${id}" width="160" height="132"></canvas>`).join('')}</div><span class="home-art-caption">SEVEN HEROES. ONE LAST LIGHT.</span></div><footer class="home-footer"><div class="home-record"><span>YOUR LONGEST SURVIVAL</span><strong>${format(best)}</strong></div><p>7 classes<span>·</span>10 realms<span>·</span>Endless survival</p></footer></main>`);
 for(const portrait of overlay.querySelectorAll?.('[data-home-portrait]')||[])renderer.portrait(portrait,portrait.dataset.homePortrait);
 paintPixelWordmark($('#pixel-wordmark'));
 $('#play').onclick=()=>{tone(430,.05);showMenu()};$('#home-guide').onclick=()=>{guide('controls');openModal('#guide-dialog')};$('#home-leaderboard').onclick=()=>$('#leaderboard-button').onclick();$('#home-settings').onclick=()=>$('#settings').onclick();$('#play').focus();announce('Welcome to Emberfall. Play to choose your hero, or explore the field guide, leaderboard, and settings.');
}
function showMenu(){prepareMenu('classes');
 setPanel(`<div class="menu"><button id="back-main" class="menu-back">Back to main menu</button><div class="menu-heading"><div><div class="eyebrow">ONE HERO. AN ENDLESS HORDE.</div><h1>Choose your <em>last light.</em></h1><p>Ten realms. One endless fight.<br>Choose a class, forge a build, and see how long you can survive.</p></div><div class="record"><span>LONGEST SURVIVAL</span><strong>${format(best)}</strong></div></div><div class="choose-label"><span>CHOOSE YOUR CLASS</span><small>Seven ways to carry the flame</small></div><div class="class-grid">${classes.map(c=>`<button class="class-card ${selectedClass===c.id?'selected':''}" data-class="${c.id}" aria-pressed="${selectedClass===c.id}" style="--class-color:${c.color}"><span class="selected-check">${selectedClass===c.id?'+':''}</span><canvas class="class-portrait" data-portrait="${c.id}" width="160" height="132" aria-hidden="true"></canvas><span class="class-icon">${c.icon}</span><h2>${c.name}</h2><span class="class-tag">${c.tag}</span><p>${c.description}</p><ul>${c.perks.map(p=>`<li>${p}</li>`).join('')}</ul><div class="class-active" title="${activeSkills[c.id].description}"><kbd>SPACE</kbd><strong>${activeSkills[c.id].name}</strong></div></button>`).join('')}</div><div class="menu-bottom"><div class="menu-notes"><div><span>◇</span>Finite arena</div><div><span>✦</span>${talents.length} stacking abilities</div><div><span>♞</span>7 unique companions</div><div><span>☠</span>3 bosses + 3 minibosses</div></div><button id="start" class="gold-button">Begin as ${classes.find(c=>c.id===selectedClass).name}<span>→</span></button></div><div class="menu-footnote">WASD / arrows to move · SPACE for your class ability · Touch controls supported · Begin enters fullscreen when available</div></div>`);
 for(const portrait of overlay.querySelectorAll?.('[data-portrait]')||[])renderer.portrait(portrait,portrait.dataset.portrait);$('#back-main').onclick=showHome;$('#back-main').focus();$('#start').onclick=start;announce('Choose one of seven classes, then begin your run.');
}
function start(){soundtrack.unlock();soundtrack.cue('start');g=createGame(Date.now(),selectedClass);g.status='playing';screenStatus='';keys.clear();touch={x:0,y:0};accumulator=0;last=performance.now();lastKills=0;lastHealth=g.health;$('#run-hud').hidden=false;$('#game-root').classList.add('running');$('#pause').disabled=false;overlay.classList.add('hidden');document.documentElement?.style.setProperty('--hero-color',classes.find(c=>c.id===g.classId).color);updateBuild();updateHUD();canvas.focus();tone(540,.15);if(!document.fullscreenElement&&document.documentElement?.requestFullscreen)fullscreen()}
function saveBest(){records.complete({time:g.time,kills:g.kills,classId:g.classId});if(g.time>best){best=g.time;try{localStorage.setItem('emberfall-best',String(best))}catch{}return true}return false}
function pause(){if(g.status==='playing'){g.status='paused';clearInput()}else if(g.status==='paused'){soundtrack.unlock();g.status='playing';last=performance.now();canvas.focus()}renderStatus()}
function clearInput(){keys.clear();touch={x:0,y:0};pointer=null;$('#joystick').classList.remove('active')}
$('#pause').onclick=pause;
function legend(){return `<div class="category-legend">${Object.values(categories).map(c=>`<span><i style="background:${c.color}"></i>${c.name}</span>`).join('')}</div>`}
function renderStatus(){if(screenStatus===g.status)return;screenStatus=g.status;updateHUD();$('#pause').disabled=!['playing','paused'].includes(g.status);$('#pause').textContent=g.status==='paused'?'PLAY':'II';$('#pause').setAttribute('aria-label',g.status==='paused'?'Resume game':'Pause game');if(g.status==='playing'){overlay.classList.add('hidden');return}
 if(g.status==='levelup'){clearInput();soundtrack.cue('level');setPanel(`<div class="level-screen" tabindex="-1"><span class="eyebrow">LEVEL ${g.level} REACHED</span><h2>The ember grows stronger.</h2><p>Time is paused. Choose one passive. You get 2 seconds of protection after choosing.</p><div class="choices">${g.choices.map((id,i)=>{const t=talents.find(t=>t.id===id);return `<button class="choice" data-talent="${id}" style="--ability-color:${colorFor(t)}"><span class="choice-rank"><kbd>${i+1}</kbd> · ${g.build[id]?'RANK '+g.build[id]+' → '+(g.build[id]+1):'NEW ABILITY'}</span><span class="choice-icon"><canvas data-pixel-icon="${t.category}" data-color="${colorFor(t)}" width="24" height="24" aria-hidden="true"></canvas></span><small>${t.type.toUpperCase()}${t.classes?' · '+classes.find(c=>c.id===g.classId).name.toUpperCase()+' ONLY':''}</small><strong>${t.name}</strong><p>${t.description}</p></button>`}).join('')}</div><span class="choose-note">Click a card, tap, or press 1 / 2 / 3</span>${legend()}</div>`);overlay.querySelector('.level-screen')?.focus();announce(`Level ${g.level}. Choose one of three passive abilities.`)}
 else if(g.status==='paused'){setPanel(`<div class="pause-screen"><span class="eyebrow">THE WOOD CAN WAIT</span><canvas class="emblem" data-pixel-icon="arcane" width="24" height="24" aria-hidden="true"></canvas><h2>A moment by the fire.</h2><p>Wave ${g.wave} · ${format(g.time)} survived · ${g.kills} kills<br>Your run and every enemy are paused.</p><div class="pause-actions"><button id="resume" class="gold-button">Return to the wilds →</button><button id="menu" class="secondary-button">End run & change class</button><button id="main-menu" class="secondary-button">End run & main menu</button></div></div>`);$('#resume').onclick=pause;$('#menu').onclick=()=>{saveBest();showMenu()};$('#main-menu').onclick=()=>{saveBest();showHome()}}
 else if(g.status==='dead'){clearInput();const record=saveBest();setPanel(`<div class="pause-screen"><span class="eyebrow">${record?'A NEW PERSONAL BEST':'THE EMBER FADES'}</span><canvas class="emblem" data-pixel-icon="arcane" width="24" height="24" aria-hidden="true"></canvas><h2>Even embers rise again.</h2><p id="run-sync-status" role="status" class="profile-note"></p><div class="run-results"><div><span>SURVIVED</span><b>${format(g.time)}</b></div><div><span>KILLS</span><b>${g.kills}</b></div><div><span>WAVE</span><b>${g.wave}</b></div><div><span>BOSSES</span><b>${g.bossKills}</b></div></div><p>${classes.find(c=>c.id===g.classId).name} · Level ${g.level} · ${g.miniKills} minibosses defeated<br>A different path. A different build. One more run?</p><div class="pause-actions"><button id="restart" class="gold-button">Try ${classes.find(c=>c.id===selectedClass).name} again →</button><button id="menu" class="secondary-button">Choose another class</button><button id="main-menu" class="secondary-button">Main menu</button></div></div>`);$('#restart').onclick=start;$('#menu').onclick=showMenu;$('#main-menu').onclick=showHome;$('#pause').disabled=true;announce(`Run complete. Wave ${g.wave}, ${g.kills} kills, ${format(g.time)} survived.`);soundtrack.cue('dead');updateProfile()}
}
function selectTalent(id){if(chooseUpgrade(g,id)){clearInput();screenStatus='';updateBuild();updateHUD();renderStatus();if(g.status==='playing')canvas.focus();tone(850,.12)}}
overlay.addEventListener('click',e=>{const classButton=e.target.closest('[data-class]');if(classButton){selectedClass=classButton.dataset.class;showMenu();tone(430,.05);return}const talentButton=e.target.closest('[data-talent]');if(talentButton)selectTalent(talentButton.dataset.talent)});
function updateBuild(){const count=Object.keys(g.build).length;$('#build-button').textContent=count?'Build · '+count:'Build'}
function updateHUD(){
 const skill=activeSkills[g.classId],cooldown=g.activeCooldown,ready=cooldown<=0;
 $('#hero-name').textContent=classes.find(c=>c.id===g.classId).name;$('#world-name').textContent=sceneAt(g.time).name;$('#world-next').textContent=format(Math.ceil(60-g.time%60));
 $('#health-fill').style.width=Math.max(0,g.health/g.stats.maxHealth*100)+'%';$('#health-text').textContent=Math.ceil(g.health)+' / '+g.stats.maxHealth;
 $('#health-track').setAttribute('aria-valuenow',Math.ceil(g.health));$('#health-track').setAttribute('aria-valuemax',g.stats.maxHealth);
 $('#shield-fill').style.width=Math.min(100,totalShield(g)/g.stats.maxHealth*100)+'%';$('#health-track').setAttribute('aria-valuetext',Math.ceil(g.health)+' HP and '+Math.ceil(totalShield(g))+' shield');
 $('#shield-text').textContent=totalShield(g)>0?'⬡ '+Math.ceil(totalShield(g))+(g.guardianWard>0?' / '+g.guardianWard.toFixed(1)+'s':''):'';
 $('#xp-fill').style.width=Math.min(100,g.xp/g.nextXP*100)+'%';$('#xp-track').setAttribute('aria-valuenow',Math.floor(g.xp));$('#xp-track').setAttribute('aria-valuemax',g.nextXP);
 $('#level').textContent=g.level;$('#time').textContent=format(g.time);$('#kills').textContent=g.kills;
 $('#time').title='Wave '+g.wave+' · Threat '+Math.ceil(liveThreat(g))+' / '+threatBudget(g);
 const activeIcon=$('#active-icon');if(activeIcon.dataset.classId!==g.classId+':'+ready){activeIcon.innerHTML='<canvas width=24 height=24 aria-hidden=true></canvas>';paintPixelIcon(activeIcon.querySelector('canvas'),g.classId,ready?'#24312a':skill.color);activeIcon.dataset.classId=g.classId+':'+ready}$('#active-name').textContent=skill.name;$('#active-seconds').textContent=g.classId==='archer'&&g.activeTime>0?g.activeTime.toFixed(1)+'s':ready?'READY':Math.ceil(cooldown)+'s';$('#active-state').textContent=g.classId==='archer'&&g.activeTime>0?'ARROWSTORM ACTIVE':ready?'SPACE / tap':Math.ceil(cooldown)+'s remaining';
 $('#active-button').disabled=g.status!=='playing'||!ready;$('#active-button').title=skill.description;
 $('#active-button').setAttribute('aria-label',skill.name+(ready?', ready. Press Space or tap':', '+Math.ceil(cooldown)+' seconds remaining'));
 $('#active-button').style.setProperty('--active-color',skill.color);if(ready)$('#active-button').classList.add('ready');else $('#active-button').classList.remove('ready');
 $('#protection').hidden=g.levelGuard<=0;$('#protection').textContent='SAFE '+g.levelGuard.toFixed(1)+'s';
 const boss=g.nextBoss<=g.nextMini;$('#event-label').textContent=g.pendingElites.length?'ELITE WAITING':boss?'BOSS':'MINIBOSS';$('#event-time').textContent=g.pendingElites.length?'Clear foes':format(Math.ceil(Math.max(0,(boss?g.nextBoss:g.nextMini)-g.time)));
 $('#announcement').hidden=g.announcementLife<=0;$('#announcement').textContent=g.announcement;
}
function abilityCard(t,rank){return `<article class="guide-card" style="--ability-color:${colorFor(t)}"><div class="guide-card-top"><span>${t.type.toUpperCase()}</span><span class="guide-icon"><canvas data-pixel-icon="${t.category}" data-color="${colorFor(t)}" width="24" height="24" aria-hidden="true"></canvas></span></div><h3>${t.name}</h3>${t.classes?'<span class=class-badge>'+t.classes.map(id=>classes.find(c=>c.id===id).name).join(' / ')+' ONLY</span>':''}<p>${t.description}</p>${rank?`<div class="rank">RANK ${rank}${t.max?' / '+t.max:''}</div>`:t.max?`<div class="rank">Up to ${t.max} ranks</div>`:''}</article>`}
function guide(tab='abilities'){$('#abilities-tab').classList.remove('selected');$('#monsters-tab').classList.remove('selected');$('#controls-tab').classList.remove('selected');$(`#${tab}-tab`).classList.add('selected');if(tab==='abilities')$('#guide-content').innerHTML=`<h3 class="guide-active-heading">YOUR CLASS ACTIVE · SPACE · NOT A PASSIVE UPGRADE</h3><div class="guide-grid">${classes.filter(c=>c.id===g.classId).map(c=>{const a=activeSkills[c.id];return `<article class="guide-card active-guide" style="--ability-color:${a.color}"><div class="guide-card-top"><span>${c.name.toUpperCase()} · ACTIVE</span><span class="guide-icon"><canvas data-pixel-icon="${c.id}" data-color="${a.color}" width="24" height="24" aria-hidden="true"></canvas></span></div><h3>${a.name}</h3><p>${a.description}</p><div class="rank">SPACE / tap · ${a.cooldown}s cooldown</div></article>`}).join('')}</div><h3 class="guide-active-heading">CLASS PASSIVES · ${classes.find(c=>c.id===g.classId).name.toUpperCase()}</h3>${legend()}<p class="guide-help">${talents.length} abilities. The total spans all seven classes. Colors show their school; labels identify it too. Your Space ability is separate and never appears in passive choices. All classes can learn companions and additional weapons. Class-only upgrades are labeled and offered at every level while eligible upgrades remain.</p><div class="guide-grid">${talents.filter(t=>t.classes?.includes(g.classId)).map(t=>abilityCard(t)).join('')}</div><h3 class="guide-active-heading">COMMON PASSIVES · ALL CLASSES</h3><div class="guide-grid">${talents.filter(t=>!t.classes).map(t=>abilityCard(t)).join('')}</div>`;else if(tab==='monsters')$('#guide-content').innerHTML=`<p class="guide-help">Each monster has its own XP reward, before your XP bonuses. Minibosses arrive every 45 seconds; the three main bosses rotate every 2 minutes. An elite may wait until the live enemy difficulty budget has room.</p><div class="guide-grid">${Object.values(monsters).map(m=>`<article class="guide-card" style="--ability-color:${m.color}"><div class="guide-card-top"><span>${m.boss?'BOSS':m.mini?'MINIBOSS':'MONSTER'}</span><strong>${m.xp} XP</strong></div><h3>${m.name}</h3><p>${m.description}</p><div class="rank">Difficulty ${m.cost} · Base health ${m.hp} · Contact damage ${m.damage}</div></article>`).join('')}</div>`;else $('#guide-content').innerHTML=`<div class="guide-help"><h3>Carry the flame</h3><p>Move with <b>WASD</b> or <b>arrow keys</b>. On touch screens, drag the arena. Your class attacks automatically when a target is in range. The thin bar above your head fills as your basic attack recharges and turns pale green when ready. Press <b>Space</b> or tap the circular ability button to use your unique class active. Its saturated icon and timer show when it is ready. Archer, Mage and Healer fight at range. Fighter, Assassin, Tank and Shapeshifter hit nearby enemies in an area. Their transparent circle shows primary attack reach and grows with reach/area upgrades. It is separate from ultimate and secondary-weapon range.</p><h3>The Hollow Wood</h3><p>The realm changes every 60 seconds of survival, cycling through ${scenes.map(s=>s.name).join(', ')}. Obstacle artwork changes with the realm; their solid footprints stay in place during that run. A new run generates a new spread of obstacles with clear routes and a safe starting area. Pauses and level-up decisions stop the realm clock. A finite ${MAP.right-MAP.left} × ${MAP.bottom-MAP.top} arena. Walls and stone ruins block movement. The compact top-right panel shows health, XP, level, time and kills. Boss health is above its head. The waves never end, but spawning obeys a difficulty budget: 18 points plus 0.45 per second. Strong monsters cost more points. At most 96 enemies can be alive. Hover over the run clock to inspect the wave and enemy budget. Bosses and summons obey the same cap; an elite waits for room if necessary.</p><h3>Know the clock</h3><ul><li>Each wave lasts <b>30 seconds</b> and increases spawn pressure.</li><li>A miniboss appears every <b>45 seconds</b>: Ravager, Broodmother, then Mire Hexer.</li><li>A main boss appears every <b>120 seconds</b>: Stone Warden, Frost Revenant, then Ashen Dragon. Elites wait for room in the difficulty budget. The sequence repeats with stronger enemies.</li></ul><h3>Build your hero</h3><p>Kills grant XP immediately. Level-ups pause the world and offer three abilities. Pick with a click, tap, or <b>1–3</b>. Passives stack. You are protected from all damage for 2 seconds after choosing. A class-specific upgrade is offered while eligible upgrades remain. A combat companion is offered at your first level-up. Each kind can exist only once. Further ranks strengthen that same companion. The four combat pets choose their own targets. Dew sprite restores 0.3 HP/s; Hourglass moth slows nearby hostile shots; Lastlight sacrifices itself against one fatal hit, grants a 2-second shield worth 25% of maximum HP, and cannot return this run. Review your passives with <b>B</b> or View build.</p><h3>New classes and inherited aspects</h3><p>Tank has 200 HP, 40% damage reduction, a rechargeable shield, and area bashes. Healer uses radiant splash bolts and restores 0.25 HP/s; Sanctuary heals and clears nearby shots. Shapeshifter starts with only 70 HP and weak claws. Each elite kill grants its permanent aspect: Ravager speed and strikes, Broodmother venom, Hexer curses, Warden armor and stomps, Frost Revenant freeze, or Dragon fire. Repeated kills strengthen that aspect. View inherited ranks in your build.</p><h3>Healing under pressure</h3><p>Second wind restores only 0.2 HP/s per rank, up to 1 HP/s, and starts only after 6 seconds without damage. Kill-healing is capped at 0.8 HP/s. Shields recharge at 2 points/s after 8 seconds without damage. Healing cannot erase repeated hits.</p><h3>Read the battlefield</h3><p>Bright warning circles, red aim lines, and charge paths warn you of incoming attacks. Hostile arrows are hot pink, ice is bright cyan, fire is orange-red, and poison is neon green. Bright, outlined projectiles and brief pixel bursts mark casts, impacts, and defeats. Move before they activate. Solid colored pools deal damage. Frost slows; fire and poison damage foes over time. Bosses resist crowd-control durations and knockback.</p><p><b>P / Esc</b> pauses. <b>F</b> toggles fullscreen. <b>M</b> mutes audio. Audio settings have separate music and combat volume sliders. Leaving the tab pauses automatically. Death ends the run; your longest survival is saved on this device.</p></div>`}
function openModal(selector){decorateIcons(document);const running=g.status==='playing';if(running)pause();$(selector).showModal();$(selector).addEventListener('close',()=>{if(running&&g.status==='paused')pause()},{once:true})}
$('#codex').onclick=()=>{guide('abilities');openModal('#guide-dialog')};$('#abilities-tab').onclick=()=>{guide('abilities');decorateIcons($('#guide-content'))};$('#monsters-tab').onclick=()=>guide('monsters');$('#controls-tab').onclick=()=>guide('controls');
function viewBuild(){if(g.status==='ready')return;$('#build-title').textContent=`${classes.find(c=>c.id===g.classId).name} · Level ${g.level}`;$('#build-stats').innerHTML=`<span>Damage <b>${Math.round(g.stats.damage)}</b></span><span>Attacks / sec <b>${(1/Math.max(.09,g.stats.interval)).toFixed(1)}</b></span><span>Speed <b>${Math.round(g.stats.speed)}</b></span><span>Crit <b>${Math.round(g.stats.crit*100)}%</b></span><span>Companions <b>${g.pets.length}</b></span><span>Regen <b>${(Math.min(1,g.stats.regen)+g.stats.classRegen+(g.pets.some(p=>p.kind==='healerpet')?.1:0)).toFixed(2)}/s</b></span>`;const entries=Object.entries(g.build);$('#build-details').innerHTML=(entries.length?entries.map(([id,rank])=>abilityCard(talents.find(t=>t.id===id),rank)).join(''):'<p class="guide-help">No passives yet. Defeat enemies and level up to choose your first ability.</p>')+Object.entries(g.absorbed).map(([kind,rank])=>'<article class="guide-card"><div class="class-badge">INHERITED · RANK '+rank+'</div><h3>'+essences[kind].name+'</h3><p>'+essences[kind].description+'</p></article>').join('')+(g.guardianSpent?'<p class="guide-help">Lastlight sacrificed itself. It cannot be summoned again this run.</p>':'');openModal('#build-dialog')}
$('#build-button').onclick=viewBuild;
function movement(){return{x:(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+touch.x,y:(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0)+touch.y}}
function useActive(){soundtrack.unlock();if(activate(g,movement())){updateHUD();canvas.focus()}}
$('#active-button').onclick=useActive;
$('#guide-dialog .close').onclick=()=>$('#guide-dialog').close();$('#build-dialog .close').onclick=()=>$('#build-dialog').close();
const movementKeys=['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowLeft','ArrowDown','ArrowRight'];
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target?.tagName))return;if(e.code==='Space'&&g.status==='levelup'){e.preventDefault();e.stopPropagation?.();return}if(e.code==='KeyM'&&!e.repeat){e.preventDefault();toggleAudio();return}if($('#guide-dialog').open||$('#build-dialog').open||$('#audio-dialog').open||$('#leaderboard-dialog').open)return;if(e.code==='Space'&&g.status==='playing'){e.preventDefault();if(!e.repeat)useActive();return}if(movementKeys.includes(e.code)&&g.status==='playing'){e.preventDefault();keys.add(e.code)}if(e.repeat)return;if(e.code==='KeyF'){e.preventDefault();fullscreen()}if(e.code==='Escape'&&g.status==='ready'&&menuPage==='classes'){e.preventDefault();showHome();return}if(['Escape','KeyP'].includes(e.code)){e.preventDefault();pause()}if(e.code==='KeyB'){e.preventDefault();viewBuild()}if(g.status==='levelup'&&['Digit1','Digit2','Digit3'].includes(e.code)){e.preventDefault();selectTalent(g.choices[Number(e.code.at(-1))-1])}else if(g.status==='ready'&&menuPage==='classes'&&/^Digit[1-7]$/.test(e.code)){selectedClass=classes[Number(e.code.at(-1))-1].id;showMenu()}});document.addEventListener('keyup',e=>{keys.delete(e.code);if(e.code==='Space'&&g.status==='levelup'){e.preventDefault();e.stopPropagation?.()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&g.status==='playing')pause();soundtrack.update(g.status,document.hidden)});window.addEventListener('blur',()=>{keys.clear();if(g.status==='playing'&&performance.now()>fullscreenTransition)pause()});
canvas.addEventListener('pointerdown',e=>{if(g.status!=='playing')return;e.preventDefault();canvas.focus();if(e.pointerType==='mouse')return;pointer={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);$('#joystick').style.left=`${e.clientX-45}px`;$('#joystick').style.top=`${e.clientY-45}px`;$('#joystick').classList.add('active')});canvas.addEventListener('pointermove',e=>{if(!pointer||pointer.id!==e.pointerId)return;const x=e.clientX-pointer.x,y=e.clientY-pointer.y,d=Math.max(38,Math.hypot(x,y));touch={x:x/d,y:y/d};$('#stick').style.transform=`translate(${x/d*26}px,${y/d*26}px)`});function release(e){if(pointer?.id!==e.pointerId)return;pointer=null;touch={x:0,y:0};$('#joystick').classList.remove('active');$('#stick').style.transform='none'}canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);
let menuAnimationFrame=-1;
function frame(now){if(g.status==='ready'&&!renderer.reducedMotion){const f=Math.floor(now/250)%4;if(f!==menuAnimationFrame){menuAnimationFrame=f;for(const portrait of overlay.querySelectorAll?.('[data-portrait],[data-home-portrait]')||[])renderer.portrait(portrait,portrait.dataset.portrait||portrait.dataset.homePortrait,f)}}const dt=last?Math.min(.1,(now-last)/1000):0;last=now;if(g.status==='playing'){accumulator+=dt;const input=movement();let steps=0;while(accumulator>=1/60&&steps++<6&&g.status==='playing'){step(g,1/60,input);accumulator-=1/60}hudClock+=dt;if(hudClock>.12){updateHUD();hudClock=0}}else accumulator=0;for(const cue of g.audioEvents.splice(0))soundtrack.cue(cue);soundtrack.update(g.status,document.hidden);renderStatus();if(g.status==='playing'?now-lastDraw>=1000/renderer.targetFPS-.5:drawStatus!==g.status){renderer.draw(g);lastDraw=now-(now-lastDraw)%(1000/renderer.targetFPS);drawStatus=g.status}requestAnimationFrame(frame)}
$('.brand').onclick=e=>{e.preventDefault();if(g.status==='ready')showHome()};
showHome();requestAnimationFrame(frame);
